<script>
 import {isGraphJoin,isGraphPredicate} from '@adam-flow/core/flow-core/graph-controls.js';
 import InputTypeEditor from './InputTypeEditor.svelte';
 export let binding;export let disabled=false;export let onApply;
 let draft,error='',open=false;
 function begin(){draft=structuredClone(binding.signature);error='';}
 function add(direction){let index=1;while(draft[direction].some(p=>p.name===`value${index}`))index++;draft={...draft,[direction]:[...draft[direction],{name:`value${index}`,nodeId:`parameter_${crypto.randomUUID()}`,type:{kind:'string'}}]};}
 function update(direction,id,changes){draft={...draft,[direction]:draft[direction].map(p=>p.nodeId===id?{...p,...changes}:p)};}
 async function apply(){try{const next=structuredClone(draft);if(binding.operation==='while')next.outputs=next.inputs.map(p=>({...p}));if(binding.operation==='aggregate'){const accumulator=next.inputs.find(p=>p.name==='accumulator');if(!accumulator)throw new Error('Aggregate benötigt den Eingang accumulator.');next.outputs=[{...accumulator,nodeId:'accumulatorResult'}];}if(isGraphPredicate(binding.operation))next.outputs=[{name:'value',nodeId:next.outputs[0]?.nodeId??'value',type:{kind:'scalar',name:'core.Bool'}}];if(await onApply(next)!==false)open=false;}catch(cause){error=String(cause);}}
</script>
<details bind:open on:toggle={()=>{if(open)begin();}}><summary>Schnittstelle bearbeiten</summary>
 {#if draft}
 <p>{isGraphJoin(binding.operation)?'leftItem und rightItem legen die Elementtypen der beiden Listen fest. Jeder Schlüssel-Graph erhält item und index seiner Liste und liefert value als gemeinsamen Schlüsseltyp. Weitere Eingaben werden an beide Graphen weitergereicht.':binding.operation==='sortBy'?'Der Body liefert einen Schlüssel oder einen Record aus mehreren Schlüsseln. Bei einem Record legt orderBy die Feldreihenfolge und die jeweilige Sortierrichtung fest.':binding.operation==='parallelMap'?'Der Body erhält item und index. maxConcurrency begrenzt gleichzeitige Aufrufe auf 1–16. Ergebnisse bleiben in Eingabereihenfolge. Jeder Aufruf bekommt eigene Daten und einen eigenen Backend-Kontext; nur transportierbare Ein- und Ausgaben sind erlaubt.':binding.operation==='retry'?'Der Body erhält attempt (ab 1). Nur explizit in retryCodes enthaltene Fehler werden wiederholt. Du bist für die Idempotenz von Schreiboperationen verantwortlich.':binding.operation==='repeat'?'Der Body erhält index (0 bis count−1), liefert keine Ergebnisse und läuft sequenziell. count ist auf 0–1000 begrenzt. Weitere Eingaben bleiben unverändert.':binding.operation==='while'?'Schleifenwerte werden an Bedingung und Body übergeben. Der Body gibt diese Werte für den nächsten Durchlauf zurück.':binding.operation==='aggregate'?'item und index beschreiben das aktuelle Element. accumulator enthält den bisherigen Wert und wird vom Body mit demselben Typ zurückgegeben. Weitere Eingaben werden unverändert durchgereicht.':isGraphPredicate(binding.operation)?'Der Body erhält item und index und liefert value als Bool. Weitere Eingaben werden unverändert durchgereicht.':binding.operation==='flatMap'?'Der Body erhält item und index und liefert value als Liste. Die Ergebnislisten werden in Eingabereihenfolge zusammengeführt.':'Die Schnittstelle bestimmt die Anforderungen der Graph-Eingänge.'}</p>
 {#each ((['while','aggregate','repeat'].includes(binding.operation)||isGraphPredicate(binding.operation))?['inputs']:['inputs','outputs']) as direction}<strong>{direction==='inputs'?'Eingaben':'Ergebnisse'}</strong>{#each draft[direction] as parameter (parameter.nodeId)}<div class="parameter"><input aria-label={`${direction}: Parametername`} {disabled} value={parameter.name} on:input={event=>update(direction,parameter.nodeId,{name:event.target.value})}/><InputTypeEditor type={parameter.type} allowOptional {disabled} on:type={event=>update(direction,parameter.nodeId,{type:event.detail})}/><button {disabled} on:click={()=>draft={...draft,[direction]:draft[direction].filter(p=>p.nodeId!==parameter.nodeId)}}>Entfernen</button></div>{/each}<button {disabled} on:click={()=>add(direction)}>{direction==='inputs'?'Eingabe':'Ergebnis'} hinzufügen</button>{/each}
 <label><input type="checkbox" bind:checked={draft.control.input} {disabled}/>Ablauf-Eingang der Subgraphen</label><label><input type="checkbox" bind:checked={draft.control.output} {disabled}/>Ablauf-Ausgang der Subgraphen</label>
 <button {disabled} on:click={apply}>Schnittstelle übernehmen</button>{#if error}<p role="alert">{error}</p>{/if}
 {/if}
</details>
<style>details{padding:8px;font-size:12px;border-top:1px solid var(--w-border,#ddd)}.parameter{padding:6px 0}input,button{font:inherit;max-width:100%;box-sizing:border-box}strong,label{display:block;margin-top:6px}p[role=alert]{color:#b91c1c}</style>
